<?php  namespace QASI\modules\tietuku_oss; use qqworld_collector\lib\options; class tietuku extends \qqworld_collector_common { var $slug = 'tietuku'; var $tietuku; var $protocol; var $token; public function __construct() { $this->options = new options; add_filter( 'qqworld-auto-save-images-media-library-mode', array($this, 'add_media_library_mode') ); add_action( 'qqworld-auto-save-images-media-library-form', array($this, 'add_media_library_form') ); $this->optimize = get_option('qqworld-auto-save-images-optimize', array('enabled' => 'no', 'mode' => 'local')); $this->tietuku = get_option( 'qqworld-auto-save-images-tietuku', array('token' => '', 'protocol' => 1) ); $this->protocol = isset($this->tietuku['protocol']) ? $this->tietuku['protocol'] : 1; $this->token = isset($this->tietuku['token']) ? $this->tietuku['token'] : ''; $this->delete_attachment_after_synced = isset($this->tietuku['delete-attachment-after-synced']) ? $this->tietuku['delete-attachment-after-synced'] : 'no'; add_filter( 'qqworld-auto-save-images-exclude-domain-'.$this->slug, array($this, 'exclude_domain') ); add_action( 'qqworld-auto-save-images-sync-oss-'.$this->slug, array($this, 'sync_tietuku'), 10, 3 ); add_filter( 'qqworld-auto-save-images-manage-media-columns-'.$this->slug, array($this, 'manage_media_columns') ); add_action( 'qqworld-auto-save-images-manage-media-custom-column', array($this, 'manage_media_custom_column'), 10, 2 ); add_action( 'qqworld-auto-save-images-optimize-'.$this->slug, array($this, 'optimize_action') ); add_action( 'wp_ajax_auto_save_images_get_attachments_list_'.$this->slug, array($this, 'get_attachments_list') ); add_action( 'wp_ajax_nopriv_auto_save_images_get_attachments_list_'.$this->slug, array($this, 'get_attachments_list') ); add_action( 'wp_ajax_qqworld_auto_save_images_sync_'.$this->slug, array($this, 'sync_single_tietuku') ); add_action( 'wp_ajax_nopriv_qqworld_auto_save_images_sync_'.$this->slug, array($this, 'sync_single_tietuku') ); add_action( 'wp_ajax_qqworld_auto_save_images_sync_tietuku_single_attachment', array($this, 'ajax_sync_single_tietuku') ); add_action( 'wp_ajax_nopriv_qqworld_auto_save_images_sync_tietuku_single_attachment', array($this, 'ajax_sync_single_tietuku') ); } public function get_attachments_list() { if (!current_user_can($this->options->authorization)) return; $mode = $_REQUEST['mode']; $paged = $_REQUEST['paged']; switch ($mode) { case 'fast': $args = array( 'post_type' => 'attachment', 'post_mime_type' => 'image', 'meta_key' => '_sync_tietuku', 'meta_value' => 1, 'meta_compare' => 'NOT EXISTS', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); break; case 'smart': $args = array( 'post_type' => 'attachment', 'post_mime_type' => 'image', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); break; } $attachments = get_posts($args); if (!empty($attachments)) { switch ($mode) { case 'fast': $success_message = sprintf(_n('%d no synced attachment found, syncing...', '%d no synced attachments found, syncing...', count($attachments), $this->text_domain), number_format_i18n(count($attachments))); break; case 'smart': $success_message = sprintf(_n('%d attachment found, scanning...', '%d attachments found, scanning...', count($attachments), $this->text_domain), number_format_i18n(count($attachments))); break; } $array = array(); foreach ($attachments as $attachment) $array[] = $attachment->ID; $results = array( 'success' => 1, 'msg' => $success_message, 'attachments' => $array ); } else { $failed_message = __('Congratulations, seems like all attachments had already synced.', $this->text_domain); $results = array( 'success' => 0, 'msg' => $failed_message ); } echo json_encode($results); exit; } public function sync_single_tietuku($attachment_id=null) { if ( !current_user_can( $this->options->authorization ) ) return; if (!$attachment_id) { $attachment_id = $_POST['attachment_id']; } $results = $this->sync($attachment_id); echo json_encode($results); exit; } public function sync_tietuku($metadata, $attachment_id, $optimize_url) { $this->sync($attachment_id, null, $metadata); } public function sync($attachment_id, $attachment=null, $metadata=null, $mode='fast') { if ($attachment) { $type = is_object($attachment) ? $attachment->post_mime_type : $attachment['post_mime_type']; } else { $attachment = get_post($attachment_id); $type = $attachment->post_mime_type; } $metadata = $metadata ? $metadata : wp_get_attachment_metadata( $attachment_id ); $results = array( 'success' => 0, 'type' => $type, 'metadata' => $metadata, 'attachment' => $attachment ); $sizes = $this->parse_metadata($attachment_id, $metadata); if (in_array($type, $this->allowed_image_types)) { $uploaded = array(); if (!empty($sizes)) foreach ($sizes as $label => $size) { $source_path = $size['source_path']; $allow = false; switch ($mode) { case 'fast': if (file_exists($source_path)) $allow = true; break; } if ($allow) { $url = $this->upload_by_file($source_path); if ($url) { $uploaded[$label] = $url; $sizes[$label]['url'] = $url; } } else unset($sizes[$label]); } $results['sizes'] = $sizes; $this->auto_replace($attachment_id, $type, $sizes, $uploaded); } if ( !empty($uploaded) ) { $results['success'] = 1; update_post_meta($attachment_id, '_sync_tietuku', 1); update_post_meta($attachment_id, '_sync_tietuku_sizes_url', $uploaded); define('CDN_UPLOADED_'.$attachment_id, 1); } return $results; } public function auto_replace($attachment_id, $type, $sizes, $uploaded) { global $wpdb; remove_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); remove_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); $metadata = wp_get_attachment_metadata( $attachment_id ); $queues = array(); if (in_array($type, $this->allowed_image_types)) { if (!empty($sizes)) foreach ($sizes as $name => $size) { $queues[$name] = array(); $original_url = wp_get_attachment_image_src($attachment_id, $name); $queues[$name]['source_url'] = $original_url[0]; $queues[$name]['destination_url'] = $uploaded[$name]; } } if (!empty($queues)) foreach ($queues as $queue) { $source_url = $queue['source_url']; $destination_url = $queue['destination_url']; if (!empty($source_url) && !empty($destination_url)) { $sql = "UPDATE `{$wpdb->posts}` SET `post_content` = REPLACE(`post_content`, '{$source_url}', '{$destination_url}')"; $wpdb->query($sql); $old_uploaded = get_post_meta($post_id, '_sync_tietuku_sizes_url', true); if ($old_uploaded) foreach ($old_uploaded as $size => $old_url) { $new_url = $uploaded[$size]; if ($new_url) { $sql = "UPDATE `{$wpdb->posts}` SET `post_content` = REPLACE(`post_content`, '{$old_url}', '{$new_url}')"; $wpdb->query($sql); } } if ($this->options->special_custom_fields_enabled == 'yes') { $post_metas = $wpdb->get_results("SELECT * FROM `{$wpdb->postmeta}` WHERE `meta_value` LIKE '%{$source_url}%'", ARRAY_A); if (!empty($post_metas)) foreach ($post_metas as $post_meta) { $post_id = $post_meta['post_id']; $meta_key = $post_meta['meta_key']; $key = null; if (!empty($this->options->special_custom_fields)) foreach ($this->options->special_custom_fields as $key => $field) { if ($field['field'] == $meta_key) { $field = $this->options->special_custom_fields[$key]; $field_type = $field['type']; switch ($field_type) { case 'string': $value = $destination_url; break; case 'array': $value = get_post_meta($post_id, $meta_key, true); $array_key = $field['array-key']; $array = preg_replace('/^\[/i', '', $array_key); $array = preg_replace('/\]$/i', '', $array); $array = explode('][', $array); $codeStr = '$value'; foreach ($array as $key) { $codeStr .= '["'.$key.'"]'; } $codeStr .= ' = "' . $destination_url . '";'; eval($codeStr); break; } update_post_meta($post_id, $meta_key, $value); } } } } } } add_filter( 'qqworld-auto-save-images-attachment-url-'.$this->slug, array($this, 'attachment_url'), 10, 2 ); add_filter( 'qqworld-auto-save-images-image-downsize-'.$this->slug, array($this, 'image_downsize'), 10, 3 ); } public function parse_metadata($attachment_id, $metadata) { $dirs = wp_upload_dir(); $path = $dirs['path']; $sizes = array(); if (isset($metadata['file'])) { $full_file = $metadata['file']; $subpath = explode('/', $full_file); array_pop($subpath); $folder_path = implode('/', $subpath); $dir = $dirs['path'] . DIRECTORY_SEPARATOR; $sizes['full'] = array( 'source_path' => $dirs['basedir'] . DIRECTORY_SEPARATOR . $metadata['file'] ); if (!empty($metadata['sizes'])) foreach ($metadata['sizes'] as $label => $size) { $sizes[$label] = array( 'source_path' => $dirs['basedir'] . '/' . $folder_path . '/' . $size['file'] ); } } else { $file = get_attached_file($attachment_id); $sizes['file'] = array( 'source_path' => $file ); }; return $sizes; } public function add_media_library_mode($modes) { $modes['tietuku'] = __('Use TieTuKu Storage Service', $this->text_domain); return $modes; } public function manage_media_columns( $cols ) { $cols["tietuku_upload"] = __("TieTuKu", $this->text_domain); return $cols; } public function manage_media_custom_column( $column_name, $id ) { switch ($column_name) { case 'tietuku_upload': $synced = get_post_meta($id, '_sync_tietuku', true); if ($synced) { echo '<input type="button" attachment-id="'.$id.'" class="button" name="sync-tietuku-again" value="'.__('Sync Again', $this->text_domain).'">'; } else { echo '<input type="button" attachment-id="'.$id.'" class="button button-primary" name="sync-tietuku-now" value="'.__('Sync Now', $this->text_domain).'">'; } break; } } public function upload_by_file($source_path) { $target_url = 'http://up.imgapi.com/'; if (function_exists('curl_file_create')) { $file = curl_file_create($source_path); } else { $file = '@' . realpath($source_path); } $post = array( 'from' => 'file', 'httptype' => $this->protocol, 'Token' => $this->token, 'file' => $file ); $ch = curl_init(); curl_setopt($ch, CURLOPT_URL,$target_url); curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_POSTFIELDS, $post); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); $result = curl_exec($ch); curl_close($ch); $result = json_decode($result, true); if (empty($result) || isset($result['code'])) return false; else return $result['linkurl']; } public function optimize_action() { add_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); add_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); add_action( 'qqworld-auto-save-images-after-sync-oss-'.$this->slug, array($this, 'do_delete_attachment_after_synced') ); } public function wp_calculate_image_srcset($sources, $size_array, $image_src, $image_meta, $attachment_id) { $is_synced = get_post_meta($attachment_id, '_sync_tietuku', true); if ($is_synced) { $uploaded = get_post_meta($attachment_id, '_sync_tietuku_sizes_url', true); foreach ($image_meta['sizes'] as $label => $size) { $width = intval($size['width']); $sources[$width]['url'] = $uploaded[$label]; } } return $sources; } public function do_delete_attachment_after_synced($res) { $attachment_id = $res['id']; $is_synced = get_post_meta($attachment_id, '_sync_tietuku', true); if ($this->delete_attachment_after_synced == 'yes' && $is_synced == 1) { wp_schedule_single_event( time() + 10, 'cron_delete_attachment_after_synced', array($attachment_id) ); } } public function image_downsize($downsize, $id, $size) { if (get_post_meta($id, '_sync_tietuku', true)) { $uploaded = get_post_meta($id, '_sync_tietuku_sizes_url', true); $metadata = wp_get_attachment_metadata( $id ); $sizes = $this->parse_metadata($id, $metadata); $image_sizes = !empty($metadata['sizes']) ? $metadata['sizes'] : null; if ( !is_array($size) ) { if (!isset($sizes[$size])) return null; $width = isset($sizes[$size]['width']) ? $sizes[$size]['width'] : ''; $height = isset($sizes[$size]['height']) ? $sizes[$size]['height'] : ''; $thumbnail = isset($uploaded[$size]) ? array($uploaded[$size], $width, $height, true) : array($uploaded['full'], $width, $height); return $size == 'full' ? array($uploaded[$size], $width, $height) : $thumbnail; } else { if ( $intermediate = image_get_intermediate_size($id, $size) ) { $width = $intermediate['width']; $height = $intermediate['height']; foreach ($image_sizes as $size_name => $size) { if ($width < $size['width'] && $height < $size['height']) { break; } } $thumbnail = isset($uploaded[$size_name]) ? array($uploaded[$size_name], $width, $height, true) : array($uploaded['full'], $width, $height); return $size_name == 'full' ? array($uploaded[$size_name], $width, $height) : $thumbnail; } else if (isset($sizes['full'])) { return array($uploaded['full'], $size[0], $size[1]); } } } } public function wp_get_attachment_url($url, $post_id) { if ( get_post_meta($post_id, '_sync_tietuku', true) ) { $uploaded = get_post_meta($post_id, '_sync_tietuku_sizes_url', true); $url = isset($uploaded['full']) ? $uploaded['full'] : ''; } return $url; } public function exclude_domain($exclude_domain) { if (!is_array($exclude_domain)) $exclude_domain = array(); $exclude_domain[] = 'img.com/'; return $exclude_domain; } public function ajax_sync_single_tietuku() { if ( !current_user_can( $this->options->authorization ) ) return; $attachment_id = $_POST['attachment_id']; $results = $this->sync($attachment_id, null, null); $msg = $results['success'] ? __('Synced', $this->text_domain) : __('Synced Failed', $this->text_domain); $results = array( 'msg' => $msg ); echo json_encode($results); exit; } public function add_media_library_form($optimize_mode) { ?>
